impl<C: FpConfig, const MIXED: bool> Ifma8<C, MIXED> {
    /// Join two four-lane values without changing their Montgomery radix.
    #[inline(always)]
    pub fn from_halves(lo: &crate::ifma::Ifma<C, MIXED>, hi: &crate::ifma::Ifma<C, MIXED>) -> Self {
        unsafe {
            Self(
                core::array::from_fn(|j| {
                    _mm512_inserti64x4::<1>(_mm512_castsi256_si512(lo.0[j]), hi.0[j])
                }),
                PhantomData,
            )
        }
    }
    /// Sum all eight independent field lanes.
    #[inline(always)]
    pub fn horizontal_sum(&self) -> Fp<C> {
        unsafe {
            let mut value = *self;
            for index in [
                _mm512_set_epi64(3, 2, 1, 0, 7, 6, 5, 4),
                _mm512_set_epi64(5, 4, 7, 6, 1, 0, 3, 2),
                _mm512_set_epi64(6, 7, 4, 5, 2, 3, 0, 1),
            ] {
                let shifted = Self(
                    value.0.map(|v| _mm512_permutexvar_epi64(index, v)),
                    PhantomData,
                );
                value = value.add(&shifted);
            }
            value.get()[0]
        }
    }
    #[inline(always)]
    pub fn halves(&self) -> (crate::ifma::Ifma<C, MIXED>, crate::ifma::Ifma<C, MIXED>) {
        unsafe {
            (
                crate::ifma::Ifma(self.0.map(|v| _mm512_castsi512_si256(v)), PhantomData),
                crate::ifma::Ifma(
                    self.0.map(|v| _mm512_extracti64x4_epi64::<1>(v)),
                    PhantomData,
                ),
            )
        }
    }
    /// Apply the same four-lane shuffle to two independent transforms.
    #[inline(always)]
    pub fn shuffle_pair<const A: usize, const B: usize, const C0: usize, const D: usize>(
        a: &Self,
        b: &Self,
    ) -> Self {
        const fn index(i: usize) -> i64 {
            if i < 4 {
                i as i64
            } else {
                (i + 4) as i64
            }
        }
        unsafe {
            let idx = _mm512_set_epi64(
                index(D) + 4,
                index(C0) + 4,
                index(B) + 4,
                index(A) + 4,
                index(D),
                index(C0),
                index(B),
                index(A),
            );
            Self(
                core::array::from_fn(|j| _mm512_permutex2var_epi64(a.0[j], idx, b.0[j])),
                PhantomData,
            )
        }
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    use crate::{FqConfig, FrConfig};
    fn check<C: FpConfig, const MIXED: bool>() {
        let mut seed = 0xfedcba987654321u64;
        let mut random = || {
            let mut bytes = [0; 64];
            for chunk in bytes.chunks_mut(8) {
                seed ^= seed << 13;
                seed ^= seed >> 7;
                seed ^= seed << 17;
                chunk.copy_from_slice(&seed.to_le_bytes());
            }
            Fp::<C>::from_random_bytes(&bytes)
        };
        let edges = [
            Fp::<C>::ZERO,
            Fp::<C>::ONE,
            -Fp::<C>::ONE,
            Fp::<C>::from_u64(2),
            Fp::from_montgomery(crate::portable::sub4(C::P, [1, 0, 0, 0]).0),
            Fp::from_montgomery(crate::portable::sub4(C::P, [2, 0, 0, 0]).0),
            Fp::from_montgomery([u64::MAX, u64::MAX, u64::MAX, C::P[3] - 1]),
            Fp::from_montgomery([u64::MAX, u64::MAX, u64::MAX, 0]),
        ];
        let mut a = core::array::from_fn(|i| edges[i]);
        for round in 0..512 {
            let b = core::array::from_fn(|i| {
                if round < edges.len() {
                    edges[(round + i) % edges.len()]
                } else {
                    random()
                }
            });
            let (av, bv) = (Ifma8::<C, MIXED>::new(&a), Ifma8::<C, MIXED>::new(&b));
            assert_eq!(av.get(), a);
            assert_eq!(
                av.horizontal_sum(),
                a.into_iter().fold(Fp::<C>::ZERO, |acc, x| acc + x)
            );
            let (lo, hi) = av.halves();
            assert_eq!(lo.get().as_slice(), &a[..4]);
            assert_eq!(hi.get().as_slice(), &a[4..]);
            assert_eq!(Ifma8::from_halves(&lo, &hi).get(), a);
            assert_eq!(
                Ifma8::shuffle_pair::<0, 5, 2, 7>(&av, &bv).get(),
                [a[0], b[1], a[2], b[3], a[4], b[5], a[6], b[7]]
            );
            assert_eq!(av.mul(&bv).get(), core::array::from_fn(|i| a[i] * b[i]));
            assert_eq!(av.add(&bv).get(), core::array::from_fn(|i| a[i] + b[i]));
            assert_eq!(av.sub(&bv).get(), core::array::from_fn(|i| a[i] - b[i]));
            assert_eq!(
                av.sum2(&bv, &bv, &av).get(),
                core::array::from_fn(|i| (a[i] * b[i]).double())
            );
            let (v, w) = (av.sub(&bv), bv.add(&av));
            assert_eq!(
                v.horizontal_sum(),
                core::array::from_fn::<_, 8, _>(|i| a[i] - b[i])
                    .into_iter()
                    .fold(Fp::<C>::ZERO, |acc, x| acc + x)
            );
            assert_eq!(
                v.sum2(&w, &w, &v).get(),
                core::array::from_fn(|i| ((a[i] - b[i]) * (a[i] + b[i])).double())
            );
            assert_eq!(
                av.difference2(&av, &bv, &bv).get(),
                core::array::from_fn(|i| a[i] * a[i] - b[i] * b[i])
            );
            assert_eq!(v.difference2(&w, &w, &v).get(), [Fp::<C>::ZERO; 8]);
            assert_eq!(av.mul(&Ifma8::one()).get(), a);
            assert_eq!(av.sub(&av).get(), [Fp::<C>::ZERO; 8]);
            a = b;
        }
    }
    #[test]
    fn fq() {
        check::<FqConfig, false>();
    }
    #[test]
    fn fr() {
        check::<FrConfig, false>();
    }
    #[test]
    fn fq_mixed() {
        check::<FqConfig, true>();
    }
    #[test]
    fn fr_mixed() {
        check::<FrConfig, true>();
    }
}
